package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;
import org.kanger.exception.*;
import org.kanger.enums.StorageLifecycleErrorCode;

/** Actual TRUST writer witness and independent Origin semantics, without IData replacement. */
final class ContextTrustedNativeWitnessMatrix {
    static int checks;static final int WORK=64000000;
    static final String BUNDLE="!$w seed(w,1)&&flag(w,1);",MID="!@w seed(w,1)&&gate(1)->mid(w,1);",DONE="!@w mid(w,1)->done(w,1);",OUT="!@w done(w,1)->out(w,1);",BAD="!@w done(w,1)->~flag(w,1);";
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static ContextNativeCandidateInspection.Limits limits(){return ContextNativeWriterMatrix.limits(WORK);}
    static boolean write(ContextNativeCandidateLeaseMatrix.Fixture f,String text,int work)throws Exception{return f.db.writeNativeProductionCandidate(f.mind,text,limits(),work,WORK,1000000,false);}
    static ContextNativeCommitException conflict(ContextNativeCandidateLeaseMatrix.Fixture f,String text)throws Exception{ContextNativeCommitException e=null;try{write(f,text,WORK);}catch(ContextNativeCommitException expected){e=expected;}require(e!=null&&e.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT&&e.getNativeEvidence()!=null,"actual native witness conflict with sealed proof");e.getNativeEvidence().check(WORK,1);require(true,"same witness request independently replayed at capacity1 after rollback");return e;}
    static void fullGate(ContextNativeCandidateLeaseMatrix.Fixture f,String text)throws Exception{ContextNativeCommitException stopped=null;try{write(f,text,1);}catch(ContextNativeCommitException e){stopped=e;}require(stopped!=null&&stopped.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE&&stopped.getPhase().equals("full-family-qualification")&&stopped.getNativeEvidence()==null,"native witness readiness cannot bypass full-family gate");}
    static void witnessDiagnostic(ContextNativeCandidateLeaseMatrix.Fixture f,String text)throws Exception{try(ContextNativeWriteBaseline baseline=ContextNativeWriteBaseline.open(f.db,f.mind,1000)){Mind child=new Mind(f.mind);try{require(child.compile(text,null,false),"actual prepared witness diagnostic child");ContextPendingProductionSnapshotSession lease=baseline.bind(child);ContextPendingProductionSnapshotSession.Decision d=lease.inspectAutomatic(16,16,16,20000,1000000,WORK,500000,WORK,WORK,100000);require(d.engine==ContextPendingProductionSnapshotSession.Engine.WITNESS&&d.witness.status==ContextProductionFamilyAssembly.Status.FIXED_POINT,"complete-family witness engine="+d.engine+" status="+(d.witness==null?"none":d.witness.status)+" reason="+(d.witness==null?"none":d.witness.reason));baseline.requireCurrent();}finally{f.mind.release(child);}}}
    static Map<UUID,Set<String>> foreign(ContextNativeCandidateLeaseMatrix.Fixture f)throws Exception{Map<UUID,Set<String>> out=new HashMap<>();for(ContextConnection c:f.db.dmzTopology()){ContextProductionInventory v=ContextProductionInventory.inspect(c.layer(),c.getTarget().getContextId(),c.getTarget().getRevision(),false,c.getInitialization(),1000);Set<String> origins=new HashSet<>();for(ContextProductionInventory.Row r:v.primary)origins.add(r.origin);out.put(v.context,origins);}return out;}
    static void privateWitness()throws Exception{
        Path dir=Files.createTempDirectory("trusted-native-witness-");System.setProperty("user.home",dir.toString());ContextNativeCandidateLeaseMatrix.create(dir,"A",BUNDLE);ContextNativeCandidateLeaseMatrix.create(dir,"B",DONE);
        for(boolean reverse:new boolean[]{false,true}){String name="X"+reverse;long durable;Map<UUID,Set<String>> members;Map<UUID,Long> pins=new HashMap<>();
            try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,name)){require(f.mind.compile("!anchor(1); "+MID,null,false),"physical X has universal producer, no witness primary");f.db.connectContext(reverse?"B":"A","own");f.db.connectContext(reverse?"A":"B","own");f.db.applyConnectionCommand(f.mind,"A","!gate(1);");f.db.saveConnections(f.mind);members=foreign(f);for(ContextConnection c:f.db.dmzTopology())pins.put(c.getTarget().getContextId(),c.getTarget().getRevision());long before=f.db.getRevision();Set<String> original=ContextNativeCommitGuardMatrix.primary(f);
                ContextNativeCommitException bad=conflict(f,BAD);require(bad.getNativeEvidence().getOppositions().stream().anyMatch(o->o.sources.size()==5&&o.sources.stream().filter(s->s.localX).count()==2&&o.sources.stream().filter(s->!s.localX).map(s->s.context).distinct().count()==2),"exact five-Source witness refutation retains both X rules, private bundle/gate and other trusted producer");for(ContextNativeBranchInspection.Opposition o:bad.getNativeEvidence().getOppositions())for(org.kanger.ContextProductionCapture.Source s:o.sources)if(!s.localX)require(pins.get(s.context)==s.revision,"witness proof preserves original initialized member pin");require(f.db.getRevision()==before&&ContextNativeCommitGuardMatrix.primary(f).equals(original),"actual witness conflict is atomic");
                witnessDiagnostic(f,OUT);fullGate(f,OUT);require(f.db.getRevision()==before&&ContextNativeCommitGuardMatrix.primary(f).equals(original),"read-only witness diagnostic and bounded writer do not publish");require(write(f,OUT,WORK),"trusted private witness rule actually publishes after both gates");require(ContextNativeCommitGuardMatrix.primary(f).equals(new HashSet<>(Arrays.asList("!anchor(1);",MID,OUT)))&&f.db.getRevision()>before,"only exact original X rules published, no transported seed/flag/gate/mid/done/out primary");require(foreign(f).equals(members),"private initialized foreign originals unchanged by actual writer");durable=f.db.getRevision();
            }
            try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,name)){require(f.db.getRevision()>=durable&&ContextNativeCommitGuardMatrix.primary(f).equals(new HashSet<>(Arrays.asList("!anchor(1);",MID,OUT))),"witness publication exact originals survive reopen");require(foreign(f).equals(members)&&f.db.dmzTopology().stream().allMatch(c->"own".equals(c.getTrustGroup()))&&f.db.dmzTopology().stream().anyMatch(c->c.getInitialization().size()==1),"reopen preserves both trusted member originals and private gate command");for(ContextConnection c:f.db.dmzTopology())require(pins.get(c.getTarget().getContextId())==c.getTarget().getRevision(),"reopen witness member pins exact");}
        }
        System.out.println("TRUSTED_NATIVE_PRIVATE_WITNESS orders=2 exactOriginalSources=true realWitnessFamily=true mandatoryGate=true actualPublication=true privateViewsReopen=true");
    }
    static void origins()throws Exception{
        Path dir=Files.createTempDirectory("trusted-native-origins-");System.setProperty("user.home",dir.toString());ContextNativeCandidateLeaseMatrix.create(dir,"A","!$u seed(u,1);");ContextNativeCandidateLeaseMatrix.create(dir,"Separate","!$u other(u,1); !@u seed(u,1)&&other(u,1)->bad(1);");RevisionRef joint=ContextNativeCandidateLeaseMatrix.create(dir,"Joint","!$u seed(u,1)&&other(u,1); !@u seed(u,1)&&other(u,1)->bad(1);");String assertion="!~bad(1);";
        for(boolean same:new boolean[]{false,true})for(boolean reverse:new boolean[]{false,true}){String name=(same?"Joint":"Separate")+reverse,donor=same?"Joint":"Separate";long revision;
            try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,name)){require(f.mind.compile("!anchor(1);",null,false),"Origin physical root");f.db.connectContext(reverse?donor:"A","own");f.db.connectContext(reverse?"A":donor,"own");f.db.saveConnections(f.mind);long before=f.db.getRevision();Map<UUID,Set<String>> original=foreign(f);
                if(same){ContextNativeCommitException e=conflict(f,assertion);require(e.getNativeEvidence().getOppositions().stream().anyMatch(o->o.sources.size()==3&&o.sources.stream().filter(v->v.localX).count()==1&&o.sources.stream().filter(v->!v.localX).allMatch(v->v.context.equals(joint.getContextId())&&v.revision==joint.getRevision())),"same-witness control refutes with own bundle+rule+actual candidate, no unrelated Origin donor");}
                else{try(ContextNativeWriteBaseline baseline=ContextNativeWriteBaseline.open(f.db,f.mind,1000)){Mind child=new Mind(f.mind);try{require(child.compile(assertion,null,false),"actual separate-Origin child");require(baseline.bind(child).inspectNative(limits()).status==ContextNativeBranchInspection.Status.STABLE_SUPPLIED,"different Source/binder0 Origins never unify just because binder number is equal");}finally{f.mind.release(child);}}
                    ContextNativeCommitException stopped=null;try{write(f,assertion,WORK);}catch(ContextNativeCommitException e){stopped=e;}require(stopped!=null&&stopped.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE&&stopped.getPhase().equals("full-family-qualification")&&stopped.toString().contains("Positive common witness pool required")&&stopped.getNativeEvidence()==null,"negative primary witness seed remains unsupported by full-family gate, never mislabeled conflict or permission");}
                require(f.db.getRevision()==before&&ContextNativeCommitGuardMatrix.primary(f).equals(Collections.singleton("!anchor(1);")),"actual separate incomplete/joint conflict both preserve physical original state");require(foreign(f).equals(original)&&f.user.getData()==f.db,"Origin qualification leaves foreign originals and actual provider intact");revision=f.db.getRevision();
            }
            try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,name)){require(f.db.getRevision()>=revision&&ContextNativeCommitGuardMatrix.primary(f).equals(Collections.singleton("!anchor(1);")),"reopen preserves exact original after incomplete/refuted Origin candidate");}
        }
        ContextNativeCandidateLeaseMatrix.create(dir,"Consumer","!@u local(u,1)->ready(u,1);");ContextNativeCandidateLeaseMatrix.create(dir,"Other","!foreignAnchor(1);");long created;
        try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,"NewOrigin")){require(f.mind.compile("!anchor(1);",null,false),"candidate existential physical baseline");f.db.connectContext("Consumer","own");f.db.connectContext("Other","own");f.db.saveConnections(f.mind);String existential="!$u local(u,1);";witnessDiagnostic(f,existential);fullGate(f,existential);require(write(f,existential,WORK),"actual candidate existential creates its own Source-owned Origin through trusted consumer");require(ContextNativeCommitGuardMatrix.primary(f).equals(new HashSet<>(Arrays.asList("!anchor(1);",existential))),"candidate existential only, derived ready never new primary");created=f.db.getRevision();}
        try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,"NewOrigin")){require(f.db.getRevision()>=created&&ContextNativeCommitGuardMatrix.primary(f).equals(new HashSet<>(Arrays.asList("!anchor(1);","!$u local(u,1);"))),"candidate-owned existential original survives durable reopen");}
        System.out.println("TRUSTED_NATIVE_ORIGINS independentVsShared=4 nativeDistinctOrigins=true signedPrimaryFamilyIncomplete=true candidateExistential=true mandatoryWitnessGate=true durableOriginals=true");
    }
}
